    ".cplfund-subtabs button.on { background: var(--seal-blue); color: var(--white); border-color: var(--seal-blue); }",
    ".cplfund-reptoolbar { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; margin: 0 0 12px; }",
